mapper.select:
SELECT c.id, c.persona_id, c.usuario_id, c.notas, c.created_at, c.updated_at, c.deleted, c.version FROM petcare.cliente c LEFT JOIN petcare.persona p ON p.id = c.persona_id AND p.deleted = FALSE
c.deleted = FALSE AND (p.nombre ILIKE '%' || #{nombre} '%' OR p.primer_apellido ILIKE '%' || #{nombre} '%') AND p.ci ILIKE '%' || #{ci} '%'
ORDER BY c.created_at DESC LIMIT #{limit} OFFSET #{offset}
